<?php
declare(strict_types=1);
namespace BSPGraph;
require_once dirname(__DIR__,2).'/museum/_lib/site.php';
use function BSPMuseum\h;
use function BSPMuseum\j;
use function BSPMuseum\start;
use function BSPMuseum\end;
const ROOT='/knowledge-graph/';
const KINDS=['time'=>'Universal time and clock observations','design'=>'Experiment designs','foundation'=>'Foundation lessons','premise'=>'Charter premises','evidence'=>'Evidence records','model'=>'Calculation models','gate'=>'Validation gates','experiment'=>'Workbenches','investigation'=>'Investigations','comparison'=>'Model comparisons','timeline'=>'Research history','archive'=>'Archived source pointers','lesson'=>'Localized lessons','glossary'=>'Glossary terms','visualization'=>'Visualizations','module'=>'Exhibits'];
function graph():array{static $g;return $g??=json_decode(file_get_contents(dirname(__DIR__).'/catalog.json'),true,512,JSON_THROW_ON_ERROR);}
function nodes():array{static $n;return $n??=array_column(graph()['nodes'],null,'id');}
function record_url(string $id):string{return ROOT.'record/?id='.rawurlencode($id);}
function text(array $in,string $k,string $default='',int $max=180):string{$v=$in[$k]??$default;if(!is_string($v)||strlen($v)>$max||!preg_match('//u',$v)||preg_match('/[\x00-\x1f\x7f]/',$v))throw new \InvalidArgumentException('Invalid '.$k);return trim($v);}
function enum(array $in,string $k,array $allowed,string $default=''):string{$v=text($in,$k,$default);if(!in_array($v,$allowed,true))throw new \InvalidArgumentException('Unknown '.$k);return $v;}
function only(array $in,array $allowed):void{foreach(array_keys($in) as $k)if(!in_array($k,$allowed,true))throw new \InvalidArgumentException('Unknown query field');}
function get_node(string $id):array{if(!isset(nodes()[$id]))throw new \OutOfBoundsException('Unknown graph record');return nodes()[$id];}
function filters(array $input):array{$p=text($input,'page','1');if(!ctype_digit($p)||(int)$p<1||(int)$p>1000)throw new \InvalidArgumentException('Invalid page');return ['q'=>text($input,'q'),'kind'=>enum($input,'kind',['',...array_keys(KINDS)]),'lang'=>enum($input,'lang',['','en','es','fr']),'page'=>(int)$p];}
function search(array $f):array{$rank=[];$terms=preg_split('/\s+/u',$f['q'],-1,PREG_SPLIT_NO_EMPTY);foreach(nodes() as $n){if(($f['kind']!==''&&$n['kind']!==$f['kind'])||($f['lang']!==''&&$n['language']!==$f['lang']))continue;$score=$terms?0:(['foundation'=>15,'evidence'=>14,'premise'=>13,'model'=>12,'gate'=>11,'experiment'=>10,'investigation'=>9,'comparison'=>8,'visualization'=>7,'timeline'=>6,'lesson'=>5,'glossary'=>4,'module'=>3,'archive'=>2][$n['kind']]??0);foreach($terms as $term){$p='/'.preg_quote($term,'/').'/iu';$s=0;foreach(['title'=>5,'summary'=>3,'id'=>2,'status'=>1] as $key=>$weight)if(preg_match($p,$n[$key]))$s+=$weight;if(!$s)continue 2;$score+=$s;}$rank[]=['score'=>$score,'node'=>$n];}usort($rank,fn($a,$b)=>$b['score']<=>$a['score']?:strcmp($a['node']['id'],$b['node']['id']));$total=count($rank);$pages=max(1,(int)ceil($total/18));$f['page']=min($pages,$f['page']);return ['filters'=>$f,'total'=>$total,'pages'=>$pages,'results'=>array_column(array_slice($rank,($f['page']-1)*18,18),'node')];}
function neighbors(string $id,string $pred=''):array{get_node($id);$a=[];foreach(graph()['edges'] as $e){if($pred!==''&&$e['predicate']!==$pred)continue;if($e['from']===$id||$e['to']===$id){$forward=$e['from']===$id;$a[]=['edge'=>$e,'direction'=>$forward?'outgoing':'incoming','node'=>get_node($forward?$e['to']:$e['from'])];}}usort($a,fn($x,$y)=>(int)in_array($x['edge']['predicate'],['contains','archivedSource'],true)<=>(int)in_array($y['edge']['predicate'],['contains','archivedSource'],true)?:strcmp($x['node']['id'],$y['node']['id'])?:strcmp($x['edge']['predicate'],$y['edge']['predicate']));return $a;}
function shortest(string $from,string $to,bool $structural=false):array{get_node($from);get_node($to);$adj=[];foreach(graph()['edges'] as $e){if(!$structural&&in_array($e['predicate'],['contains','archivedSource'],true))continue;$adj[$e['from']][]=[$e['to'],$e,true];$adj[$e['to']][]=[$e['from'],$e,false];}$queue=[[$from,[]]];$seen=[$from=>true];for($i=0;$i<count($queue);$i++){[$id,$steps]=$queue[$i];if($id===$to)return ['found'=>true,'from'=>$from,'to'=>$to,'steps'=>$steps,'maxHops'=>6,'structural'=>$structural,'interpretation'=>'Shortest editorial link path (either direction); not a logical proof, causal chain or evidence score.'];if(count($steps)>=6)continue;foreach($adj[$id]??[] as [$dest,$e,$forward]){if(isset($seen[$dest]))continue;$seen[$dest]=true;$queue[]=[$dest,[...$steps,['from'=>$id,'to'=>$dest,'edge'=>$e,'traversal'=>$forward?'forward':'reverse']]];}}return ['found'=>false,'from'=>$from,'to'=>$to,'steps'=>[],'maxHops'=>6,'structural'=>$structural,'interpretation'=>'No path within the selected six-link limit; not evidence of physical independence.'];}
function kind(string $k):string{return KINDS[$k]??$k;}
function prov_html(array $items):void{?><details class="graph-provenance"><summary>Source fields (<?=count($items)?>)</summary><?php foreach($items as $p):?><div class="prov"><a href="<?=h($p['catalog'])?>"><?=h($p['catalog'])?></a><code><?=h($p['pointer'])?></code><small>SHA-256: <?=h($p['sha256'])?></small></div><?php endforeach;?></details><?php }
function label_select(string $name,array $options,string $value,string $all):void{?><select name="<?=h($name)?>"><option value=""><?=h($all)?></option><?php foreach($options as $k=>$v):?><option value="<?=h($k)?>" <?=$value===$k?'selected':''?>><?=h($v)?></option><?php endforeach;?></select><?php }
function query_form(array $f):void{?><form class="graph-search" action="<?=ROOT?>" method="get"><label>Search records<input type="search" name="q" maxlength="180" placeholder="Photon, wall, clocks, escape…" value="<?=h($f['q'])?>"></label><label>Record type<?php label_select('kind',KINDS,$f['kind'],'All types');?></label><label>Language<?php label_select('lang',['en'=>'English','es'=>'Español','fr'=>'Français'],$f['lang'],'All languages');?></label><button class="button" type="submit">Search graph →</button></form><?php }
function card(array $n):void{?><article class="tile graph-card"><span class="eyebrow"><?=h(kind($n['kind']))?> · <?=h(strtoupper($n['language']))?></span><h3 lang="<?=h($n['language'])?>"><a href="<?=h(record_url($n['id']))?>"><?=h($n['title'])?></a></h3><p lang="<?=h($n['language'])?>"><?=h($n['summary'])?></p><?php if($n['status']):?><p class="meta"><?=h(str_replace('_',' ',$n['status']))?></p><?php endif;?><a class="small-link" href="<?=h(record_url($n['id']))?>">Inspect connections →</a></article><?php }
function home():void{\BSPMuseum\method();$error='';try{only($_GET,['q','kind','lang','page']);$res=search(filters($_GET));}catch(\InvalidArgumentException $e){http_response_code(400);$error=$e->getMessage();$res=search(filters([]));}$g=graph();start('Semantic scientific knowledge graph','Explore source-grounded connections among research premises, scientific models, evidence, validation gates, and archived research history.',ROOT,!empty($_GET));?><section class="intro graph-hero"><span class="eyebrow gold">SEMANTIC KNOWLEDGE GRAPH · 2.3</span><h1>Follow the evidence.<br><span class="gold">Trace the connections.</span></h1><p class="lead">Explore how the ArcSecs research charter, scientific models, evidence records, validation requirements and educational investigations fit together. Every relationship records where it came from.</p><div class="actions"><a class="button" href="<?=h(record_url('evidence:escape-criterion'))?>">Explore a scientific result →</a><a class="button secondary" href="<?=ROOT?>method/">Graph method &amp; API</a></div></section><div class="stats graph-stats"><div><strong><?=count($g['nodes'])?></strong><span>Distinct records</span></div><div><strong><?=count($g['edges'])?></strong><span>Directed relationships</span></div><div><strong><?=count($g['predicates'])?></strong><span>Defined relationship types</span></div><div><strong><?=count($g['sourceCatalogs'])?></strong><span>Catalog snapshots</span></div></div><section class="section"><h2>Start with a research question.</h2><div class="grid three graph-start"><?php foreach([['premise:photon-mass','From premise to measurement','Explore the original photon mass premise, then inspect the lesson, model and evidence.'],['evidence:wall-bound','From a restricted obstruction to a test','Trace the fixed-gap wall model and the validation requirements it addresses.'],['gate:F','From validation gate to research history','Identify the linked evidence for a shared calibrated cosmological model.']] as [$id,$title,$desc]):?><article class="tile"><span class="eyebrow gold">GUIDED CONNECTION</span><h3><a href="<?=h(record_url($id))?>"><?=h($title)?></a></h3><p><?=h($desc)?></p><a class="small-link" href="<?=h(record_url($id))?>">Begin exploration →</a></article><?php endforeach;?></div></section><section class="section searchpanel"><h2>Find a graph record.</h2><?php query_form($res['filters']);?><?php if($error):?><p role="alert"><?=h($error)?></p><?php endif;?><p class="meta" role="status"><?=$res['total']?> records · Page <?=$res['filters']['page']?> of <?=$res['pages']?></p></section><div class="grid graph-results"><?php foreach($res['results'] as $n)card($n);?></div><?php if(!$res['total']):?><p class="notice">No records matched the filters.</p><?php endif;?><nav class="pagination" aria-label="Graph record pages"><?php foreach(['Previous'=>-1,'Next'=>1] as $label=>$step):$p=$res['filters']['page']+$step;if($p>=1&&$p<=$res['pages']):?><a class="button secondary" href="<?=ROOT?>?<?=h(http_build_query(array_replace($res['filters'],['page'=>$p])))?>"><?=h($label)?></a><?php endif;endforeach;?></nav><section class="notice"><h2>Relationships are not proofs.</h2><p>Editorial links, model usage, language variants and archival references describe the catalogued research structure. They do not establish causality or empirical support. Read each record’s limitations and original source.</p><div class="actions"><a href="<?=ROOT?>catalog.json" download>Graph JSON</a><a href="<?=ROOT?>graph.jsonld" download>JSON-LD / RDF</a><a href="<?=ROOT?>nodes.csv" download>Nodes CSV</a><a href="<?=ROOT?>edges.csv" download>Edges CSV</a></div></section><?php end();}
function short_title(string $s,int $max=26):string{preg_match_all('/./us',$s,$a);return count($a[0])<=$max?$s:implode('',array_slice($a[0],0,$max-1)).'…';}
function diagram(array $focus,array $neighbors):void{$uniq=[];foreach($neighbors as $a){$id=$a['node']['id'];if(!isset($uniq[$id]))$uniq[$id]=$a;} $shown=array_slice(array_values($uniq),0,12);$count=count($shown);?><div class="graph-svg-wrap"><svg id="local-graph" viewBox="0 0 760 510" role="group" aria-label="Selected record and up to twelve linked records. Complete directional relationships are listed below."><circle class="orbit-guide" cx="380" cy="255" r="160"/><circle class="orbit-guide" cx="380" cy="255" r="208"/><?php $pos=[];foreach($shown as $i=>$a){$side=$i%2;$slot=intdiv($i,2);$slots=(int)ceil(($count-$side)/2);$x=$side?635:125;$y=$slots<=1?255:44+$slot*422/($slots-1);$pos[]=[$x,$y];?><line class="graph-edge" data-neighbor="<?=h($a['node']['id'])?>" x1="380" y1="255" x2="<?=round($x,2)?>" y2="<?=round($y,2)?>"/><?php }?><g class="graph-focus"><rect x="290" y="222" width="180" height="66" rx="15"/><text x="380" y="246" text-anchor="middle">Selected record</text><text x="380" y="269" text-anchor="middle"><?=h(short_title($focus['title'],24))?></text></g><?php foreach($shown as $i=>$a):[$x,$y]=$pos[$i];$n=$a['node'];?><a class="graph-node" data-neighbor="<?=h($n['id'])?>" href="<?=h(record_url($n['id']))?>" aria-label="<?=h($n['title'])?>"><title><?=h($n['title'])?></title><rect x="<?=round($x-105,2)?>" y="<?=round($y-24,2)?>" width="210" height="48" rx="10"/><text x="<?=round($x,2)?>" y="<?=round($y-3,2)?>" text-anchor="middle" class="graph-node-kind"><?=h(short_title(kind($n['kind']),24))?></text><text x="<?=round($x,2)?>" y="<?=round($y+13,2)?>" text-anchor="middle"><?=h(short_title($n['title'],32))?></text></a><?php endforeach;?></svg></div><p class="meta">Showing <?=$count?> of <?=count($uniq)?> unique neighboring records. Lines are undirected in this overview for readability; the complete list below gives original arrow direction, type and source fields. Layout and position do not encode evidence strength.</p><?php }
function path_select(string $selected,string $exclude):void{?><select name="to" id="graph-target"><option value="">Select a destination</option><?php foreach(KINDS as $k=>$label):?><optgroup label="<?=h($label)?>"><?php foreach(nodes() as $n)if($n['kind']===$k&&$n['id']!==$exclude):?><option value="<?=h($n['id'])?>" <?=$selected===$n['id']?'selected':''?>><?=h($n['title'])?> [<?=h($n['id'])?>]</option><?php endif;?></optgroup><?php endforeach;?></select><?php }
function record_page():void{\BSPMuseum\method();try{only($_GET,['id','predicate','to','structural']);$id=text($_GET,'id','foundation:photon-mass');$n=get_node($id);$pred=enum($_GET,'predicate',['',...array_keys(graph()['predicates'])]);$to=text($_GET,'to');$structural=enum($_GET,'structural',['0','1'],'0')==='1';$path=$to!==''?shortest($id,$to,$structural):null;$links=neighbors($id,$pred);}catch(\OutOfBoundsException $e){http_response_code(404);start('Graph record not found','Unknown graph record.',ROOT.'record/',true);echo '<h1>Graph record not found</h1><p><a href="'.ROOT.'">Return to the graph.</a></p>';end();return;}catch(\InvalidArgumentException $e){http_response_code(400);start('Invalid graph request','Invalid query.',ROOT.'record/',true);echo '<h1>Invalid graph request</h1><p>'.h($e->getMessage()).'</p><p><a href="'.ROOT.'">Return to the graph.</a></p>';end();return;}$g=graph();start($n['title'].' — graph record',$n['summary'],record_url($id),true);?><section class="intro"><a class="small-link" href="<?=ROOT?>">← All graph records</a><p class="eyebrow gold"><?=h(kind($n['kind']))?> · <?=h(strtoupper($n['language']))?></p><h1 lang="<?=h($n['language'])?>"><?=h($n['title'])?></h1><p class="lead" lang="<?=h($n['language'])?>"><?=h($n['summary'])?></p><p class="meta"><?=h(str_replace('_',' ',$n['status']))?> · <code><?=h($n['id'])?></code></p><div class="actions"><a class="button" href="<?=h($n['url'])?>">Open original educational record →</a><?php if(str_starts_with($n['source'],'https://')):?><a class="button secondary" href="<?=h($n['source'])?>">Original research source ↗</a><?php endif;?><a class="button secondary" href="<?=ROOT?>api/?action=node&amp;id=<?=rawurlencode($id)?>" download>Download record JSON</a></div></section><div class="graph-workspace"><section class="panel graph-panel"><div class="graph-panel-heading"><h2>Local knowledge network</h2><span class="meta"><?=count($links)?> directed relationships</span></div><?php diagram($n,$links);?></section><aside class="panel graph-panel"><h2>Record details</h2><?php foreach(['statement'=>'Original charter statement','equation'=>'Equation','limitation'=>'Scientific limitation','observation'=>'Required observation','next_test'=>'Next decisive test','pass_condition'=>'Pass condition','detail'=>'Visualization scope','path'=>'Archived path','sha256'=>'Archived fingerprint'] as $key=>$label):if(isset($n['details'][$key])&&is_string($n['details'][$key])):?><h3><?=h($label)?></h3><p class="graph-detail"><?=h($n['details'][$key])?></p><?php endif;endforeach;?><?php prov_html($n['provenance']);?><details><summary>Complete source-linked record fields</summary><pre><?=h(json_encode($n['details'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?></pre></details><p class="meta">Provenance is a catalog pointer and byte hash, not independent verification of a scientific claim.</p></aside></div><section class="section"><h2>Trace a path between two records.</h2><p>Find the shortest route through up to six declared relationships. Links may be traversed backwards; the original direction remains visible. Exhibit membership and archive links are excluded by default to avoid shortcuts through broad catalog groups.</p><form class="graph-path-form" action="<?=ROOT?>record/" method="get"><input type="hidden" name="id" value="<?=h($id)?>"><label for="graph-target">Destination record<?php path_select($to,$id);?></label><label class="graph-checkbox"><input type="checkbox" name="structural" value="1" <?=$structural?'checked':''?>> Include catalog membership and archive links</label><button class="button" type="submit">Find path</button></form><?php if($path!==null):?><div class="panel path-output" id="graph-path"><h3><?=$path['found']?'Path found · '.count($path['steps']).' links':'No path within six links'?></h3><p><?=h($path['interpretation'])?></p><?php if($path['found']):?><ol class="graph-path-list"><?php foreach($path['steps'] as $step):$e=$step['edge'];?><li><a href="<?=h(record_url($step['from']))?>"><?=h(get_node($step['from'])['title'])?></a><span class="graph-arrow"><?=$step['traversal']==='forward'?'→':'←'?> <?=h($g['predicates'][$e['predicate']]['label'])?></span><a href="<?=h(record_url($step['to']))?>"><?=h(get_node($step['to'])['title'])?></a><?php prov_html($e['provenance']);?></li><?php endforeach;?></ol><?php endif;?><a href="<?=ROOT?>api/?<?=h(http_build_query(['action'=>'path','id'=>$id,'to'=>$to,'structural'=>$structural?'1':'0']))?>" download>Download path JSON</a></div><?php endif;?></section><section class="section" id="relationships"><h2>All matching relationships</h2><form class="graph-filter" method="get" action="<?=ROOT?>record/"><input type="hidden" name="id" value="<?=h($id)?>"><label>Relationship type<?php label_select('predicate',array_map(fn($p)=>$p['label'],$g['predicates']),$pred,'All relationships');?></label><button class="button secondary" type="submit">Apply filter</button></form><label class="graph-local-filter" hidden>Filter visible neighboring records<input id="graph-neighbor-query" type="search" maxlength="180" placeholder="Filter by title or type…"></label><p id="graph-neighbor-count" role="status" class="meta"><?=count($links)?> relationships</p><div class="graph-links"><?php foreach($links as $a):$e=$a['edge'];$other=$a['node'];$p=$g['predicates'][$e['predicate']];?><article class="tile graph-link" data-neighbor="<?=h($other['id'])?>"><span class="eyebrow"><?=$a['direction']==='outgoing'?'OUTGOING →':'← INCOMING'?> · <?=h($p['label'])?></span><h3><a href="<?=h(record_url($other['id']))?>" lang="<?=h($other['language'])?>"><?=h($other['title'])?></a></h3><p class="meta"><?=h(kind($other['kind']))?> · <?=h($other['status'])?></p><p><?=h($p['definition'])?></p><?php prov_html($e['provenance']);?></article><?php endforeach;?></div><?php if(!$links):?><p class="notice">No relationships match this selection. Use all relationship types to explore the record.</p><?php endif;?></section><?php end();}
function method_page():void{$g=graph();start('Knowledge graph method and API','Relationship definitions, catalog provenance, structured graph exports and bounded graph search.',ROOT.'method/');?><section class="intro"><span class="eyebrow gold">OPEN KNOWLEDGE ARCHITECTURE</span><h1>Meaning, provenance and interoperability.</h1><p class="lead">A read-only semantic discovery layer built from the existing catalog snapshots. Relationships are explicitly declared or direct record membership, not inferred from keyword similarity. No model formula or empirical result is changed.</p></section><section class="section"><h2>Relationship vocabulary</h2><div class="grid two"><?php foreach($g['predicates'] as $id=>$p):?><article class="tile" id="<?=h($id)?>"><h3><?=h($p['label'])?></h3><p><?=h($p['definition'])?></p><code><?=h($id)?></code></article><?php endforeach;?></div></section><section class="section"><h2>Machine-readable interfaces</h2><div class="grid two"><article class="tile"><h3>Complete graph</h3><p>Stable node IDs, edge IDs, source catalog SHA-256, JSON Pointers, details and unresolved links. JSON-LD uses local vocabulary IRIs and directed triples, plus separate relationship resources preserving provenance.</p><p><a href="<?=ROOT?>catalog.json" download>JSON</a> · <a href="<?=ROOT?>graph.jsonld" download>JSON-LD</a> · <a href="<?=ROOT?>nodes.csv" download>Nodes CSV</a> · <a href="<?=ROOT?>edges.csv" download>Edges CSV</a></p></article><article class="tile"><h3>Read-only API</h3><p>GET and HEAD. Search accepts q, kind, lang, page (18 records/page). Node lookup returns all incident links or a predicate-filtered subset. Path returns up to six links and traversal direction. Unknown IDs return 404, malformed filters 400, non-read methods 405.</p><p><a href="<?=ROOT?>api/?action=summary">Summary</a> · <a href="<?=ROOT?>api/?action=search&amp;q=escape">Search</a> · <a href="<?=ROOT?>api/?action=node&amp;id=evidence%3Aescape-criterion">Node</a> · <a href="<?=ROOT?>openapi.json" download>OpenAPI</a> · <a href="<?=ROOT?>api/?action=path&amp;id=premise%3Aphoton-mass&amp;to=gate%3AC">Path</a></p></article><article class="tile"><h3>Original model execution</h3><p>Use existing calculation endpoints and the deterministic AG-UI research workspace for numerical experiments. The graph is retrieval-only; it does not perform inference, mutate records or expose an LLM.</p><a href="/research/protocol/">Research execution protocol →</a></article><article class="tile"><h3>Interpretation and limits</h3><p>Premises are not measurements. A path through the graph is not a proof, and an absent path does not demonstrate independence. Archive fingerprints are copied from catalogued provenance, not freshly verified against external URLs. No publication PDFs or private project memory are duplicated.</p><p><?=count($g['unresolvedLinks'])?> explicit catalog links could not be resolved uniquely; ambiguous links are retained in the JSON unresolved list, not guessed.</p></article></div></section><section class="section"><h2>Catalog snapshot provenance</h2><div class="grid two"><?php foreach($g['sourceCatalogs'] as $name=>$p):?><article class="tile"><h3><?=h($name)?></h3><a href="<?=h($p['url'])?>">Source catalog</a><p class="hash"><?=h($p['sha256'])?></p></article><?php endforeach;?></div></section><?php end();}
function api_node(array $n):object{static $map;if($map===null){$map=[];$raw=json_decode(file_get_contents(dirname(__DIR__).'/catalog.json'),false,512,JSON_THROW_ON_ERROR);foreach($raw->nodes as $x)$map[$x->id]=$x;}return $map[$n['id']];}
function api():void{\BSPMuseum\api_method();try{$action=enum($_GET,'action',['summary','search','node','path'],'summary');$g=graph();switch($action){case 'summary':only($_GET,['action']);$data=['nodes'=>count($g['nodes']),'edges'=>count($g['edges']),'predicates'=>$g['predicates'],'sourceCatalogs'=>$g['sourceCatalogs'],'unresolved'=>count($g['unresolvedLinks']),'catalog'=>ROOT.'catalog.json','scope'=>$g['scope']];break;case 'search':only($_GET,['action','q','kind','lang','page']);$data=search(filters($_GET));$data['results']=array_map(__NAMESPACE__.'\api_node',$data['results']);break;case 'node':only($_GET,['action','id','predicate']);$id=text($_GET,'id');$n=get_node($id);$p=enum($_GET,'predicate',['',...array_keys($g['predicates'])]);$data=['node'=>api_node($n),'relationships'=>array_map(fn($x)=>array_replace($x,['node'=>api_node($x['node'])]),neighbors($id,$p))];break;case 'path':only($_GET,['action','id','to','structural']);$data=shortest(text($_GET,'id'),text($_GET,'to'),enum($_GET,'structural',['0','1'],'0')==='1');break;}echo j(['schema'=>'beyondspacetime.graph.response.v1','version'=>'2.3.0','action'=>$action]+$data);}catch(\OutOfBoundsException $e){http_response_code(404);echo j(['error'=>$e->getMessage()]);}catch(\InvalidArgumentException $e){http_response_code(400);echo j(['error'=>$e->getMessage()]);}}
